catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        g_form.setValue("base_city", "");
        g_form.setValue("base_state", "");        
        g_form.setValue("base_manager", "");
		g_form.setValue("vacancies_available_for_this_base", "");
		g_form.hideFieldMsg("base");
        g_form.clearMessages();
        return;
    }

    var ga = new GlideAjax("RpBmsUtils");
    ga.addParam("sysparm_name", "getBaseTableInfo");
    ga.addParam("sysparm_base_table_id", newValue);

    ga.getXML(handleResponse);
}

function handleResponse(response) {
    var answer = response.responseXML.documentElement.getAttribute("answer");
    var details = JSON.parse(answer);

    g_form.setValue("base_city", details.city);
    g_form.setValue("base_state", details.state);
    g_form.setValue("vacancies_available_for_this_base", details.vacancies);
    g_form.setValue("base_manager", details.manager);


	var vacanciesCallback = details.vacancies; 
    var availableVacancies = Number(vacanciesCallback || "0");

	g_form.hideFieldMsg("base");

	if (availableVacancies <= 0) {
	g_form.showFieldMsg("base","The selected Base has no vacancies available, Please select another Base.", "error");
   }  
}
